/**
 * The workspace's temp-HOME test wrapper (SW-124). Every test command and
 * subagent brief runs through one generated script, so no session has to
 * hand-roll `HOME=$(mktemp -d) …` and none can forget it.
 */

import * as fs from "node:fs";
import * as path from "node:path";

import { dotDir } from "./dot_dir.js";

/** Also run inline in a container by the pr gate (SW-329). */
export const TEMP_HOME_SCRIPT = `#!/bin/sh
# Generated by \`werkmeister workspace init\` (SW-124); rerun it to regenerate.
# Runs <cmd...> with HOME set to a fresh temporary directory, removed on exit,
# so no test or CLI exercise reads or writes the real ~/.werkmeister.
# --no-wait first does what WERKMEISTER_NO_WAIT=1 does, without an env assignment (SW-367),
# and exports it, so a pr gate or pr open under it skips its own wait too (SW-425).
[ "\${1:-}" != --no-wait ] || { export WERKMEISTER_NO_WAIT=1; shift; }
no_wait=\${WERKMEISTER_NO_WAIT:-}
[ "$#" -gt 0 ] || { echo "usage: with-temp-home [--no-wait] <cmd> [args...]" >&2; exit 2; }
# Wait like the pr gate while host load is over budget.host_load (SW-224), before HOME
# changes so the real config's budget applies; no werkmeister on PATH, no wait.
# In the background with a trap, so killing the wrapper ends the wait too (SW-456).
[ -n "$no_wait" ] || ! command -v werkmeister >/dev/null 2>&1 || {
  # Trap before the fork: $! is empty until the job exists, so no signal can land between them.
  trap 'kill $! 2>/dev/null; exit 130' HUP INT TERM
  werkmeister internal wait-load >&2 &
  wait $!
# 75: the wait is spent and load is still over, so running would pile on (SW-540); any other failure runs.
} || { s=$?; [ "$s" -ne 75 ] || exit 75; }
tmp=$(mktemp -d) || exit 1
trap 'rm -rf "$tmp"' EXIT
trap 'exit 130' HUP INT TERM
# Corepack keeps pnpm under HOME; without this a fresh HOME re-downloads it every run.
export COREPACK_HOME="\${COREPACK_HOME:-$HOME/.cache/node/corepack}"
# OrbStack and Docker Desktop keep the compose plugin and context here (SW-285).
export DOCKER_CONFIG="\${DOCKER_CONFIG:-$HOME/.docker}"
# A temp HOME isolates files, not the daemon: unreachable unless the caller sets it (SW-264).
export WERKMEISTER_HOST="\${WERKMEISTER_HOST:-http://127.0.0.1:1}"
# An agent's shell inherits its Claude Code session's variables; CI has none (SW-332). CLAUDE_BIN stays.
unset CLAUDECODE
for v in $(env | sed -n '/^CLAUDE_CODE_[A-Za-z0-9_]*=/s/=.*//p'); do unset "$v"; done
HOME=$tmp "$@"
status=$?
# A failure under load reads as load (SW-209).
[ "$status" -eq 0 ] || echo "with-temp-home: exit $status; host load $(uptime | sed 's/.*load averages*: //; s/,//g') on $(getconf _NPROCESSORS_ONLN) cores" >&2
exit "$status"
`;

export function tempHomeWrapper(workspaceRoot: string): string {
  return path.join(dotDir(workspaceRoot), "bin", "with-temp-home");
}

/** Write the wrapper, executable, over any earlier copy; returns its path. */
export function writeTempHomeWrapper(workspaceRoot: string): string {
  const target = tempHomeWrapper(workspaceRoot);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, TEMP_HOME_SCRIPT);
  // writeFileSync's mode applies only to a file it creates.
  fs.chmodSync(target, 0o755);
  return target;
}
